/* A shared material and interaction language. No research or learning records are changed. */
(()=>{
 'use strict';
 const root=document.documentElement;document.body.classList.add('optical-system');
 const roomKinds={library:1,reader:0,evidence:2,claims:3,synthesis:4,design:5,map:6,proposal:7,review:8};
 const pageKinds={academy:0,journey:6,toolkit:5,resource:2,seminars:3,workshop:5,notebook:7};
 const lessonKinds=[0,3,1,4,8,2,6,5,7];
 const names=['Focus lens','Source archive','Evidence prism','Argument junction','Synthesis weave','Method balance','Research orbits','Draft folio','Review aperture'];
 let observer=null,raf=0,animations=new Set();
 const moving=()=>root.dataset.motion!=='off'&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&root.dataset.input!=='keyboard';
 document.addEventListener('keydown',()=>root.dataset.input='keyboard',true);document.addEventListener('pointerdown',()=>root.dataset.input='pointer',true);
 function instrument(host,kind,quiet=false){if(!host)return;host.classList.add('sculpture','lab-object');host.dataset.sculpture='instrument-'+kind;host.dataset.opticalQuiet=String(quiet);host.dataset.opticalAngle='0';host.setAttribute('aria-hidden','true');host.innerHTML='<div class="lab-object-fallback"><i></i><i></i><i></i></div><canvas aria-hidden="true"></canvas>';}
 function heading(){const page=document.body.dataset.page,room=location.hash.split('/')[2],kind=page==='research'?(roomKinds[room]??6):page==='lesson'?lessonKinds[Number(location.hash.split('/')[1])||0]:pageKinds[page];if(kind===undefined)return;
  const head=page==='research'?document.querySelector('.research-content>.research-section-label')||document.querySelector('.research-heading'):document.querySelector('.page-heading,.lesson-title,.detail-heading');if(!head||head.dataset.opticalMounted)return;head.dataset.opticalMounted='true';head.classList.add('lab-heading');
  head.querySelectorAll('.eyebrow,.heading-grid,.destination-art').forEach(el=>el.remove());
  let host=head.querySelector('.destination-scene,.lesson-visual');if(!host){host=document.createElement('div');head.append(host)}host.classList.add('lab-heading-object');instrument(host,kind,page==='research'||page==='lesson'||page==='notebook');
  const controls=document.createElement('div');controls.className='lab-object-controls';controls.innerHTML=`<span>${names[kind]}</span><button type="button" data-lab-rotate aria-label="Rotate ${names[kind].toLowerCase()}">${'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 7A8 8 0 1 0 20 14M19 3v5h-5"/></svg>'}</button><button type="button" data-lab-reset aria-label="Reset ${names[kind].toLowerCase()} view"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 9V5h4M15 5h4v4M19 15v4h-4M9 19H5v-4"/></svg></button>`;head.append(controls);
  if(page==='research'){const task=head.querySelector('.room-task');if(task)task.classList.add('lab-task')}
 }
 function directory(){const links=[...document.querySelectorAll('.space-grid>a')],kinds=[6,0,6,5,7,7,3];links.forEach((link,i)=>{const host=link.querySelector('.space-card-art');if(host&&!host.dataset.opticalMounted){host.dataset.opticalMounted='true';instrument(host,kinds[i]??0,true)}})}
 function illustrations(){let changed=false;const add=(host,kind)=>{if(!host||host.dataset.opticalMounted)return;host.dataset.opticalMounted='true';instrument(host,kind,true);changed=true};document.querySelectorAll('.lesson-card').forEach(card=>add(card.querySelector('.phase-art'),lessonKinds[Number(card.hash.split('/')[1])||0]??0));const tools={proposal:7,matrix:4,search:0,framework:3,methods:5,checklist:8};document.querySelectorAll('.resource-art').forEach(link=>add(link.querySelector('.phase-art'),tools[link.hash.split('/')[1]]??2));document.querySelectorAll('.roadmap-column').forEach((col,i)=>add(col.querySelector('.phase-art'),[0,4,5][i]));if(changed)dispatchEvent(new Event('rei:optics-refresh'));}
 function track(nav){if(nav.querySelector('.lab-selection-track'))return;const line=document.createElement('i');line.className='lab-selection-track';line.setAttribute('aria-hidden','true');nav.append(line);nav.classList.add('lab-track-host');}
 function tracks(){raf=0;document.querySelectorAll('.lab-track-host').forEach(nav=>{const selected=nav.querySelector('[aria-current]:not([aria-current=false]),[aria-selected=true],[aria-pressed=true]'),line=nav.querySelector('.lab-selection-track');if(!line||!selected){if(line)line.hidden=true;return}const r=nav.getBoundingClientRect(),s=selected.getBoundingClientRect(),vertical=nav.matches('.research-tabs')&&r.height>r.width;line.hidden=false;line.classList.toggle('lab-track-vertical',vertical);line.style.transform=vertical?`translateY(${s.top-r.top+nav.scrollTop}px) scaleY(${s.height})`:`translateX(${s.left-r.left+nav.scrollLeft}px) scaleX(${s.width})`;})}
 const queue=()=>{if(!raf)raf=requestAnimationFrame(tracks)};
 const gallery=document.querySelector('#space-navigator');if(gallery)new MutationObserver(()=>{if(gallery.open)dispatchEvent(new Event('rei:optics-refresh'))}).observe(gallery,{attributes:true,attributeFilter:['open']});
 function mount(){observer?.disconnect();animations.forEach(a=>a.cancel());animations.clear();heading();directory();illustrations();document.querySelectorAll('.lesson-flow,.research-tabs,.workspace-tabs,.filters,[aria-label="Filter lessons"],[aria-label="Filter resources"]').forEach(track);queue();observer=new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches('.lesson-card,.resource-card')||n.querySelector('.lesson-card,.resource-card')))))illustrations();queue()});observer.observe(document.querySelector('#main'),{subtree:true,childList:true,attributes:true,attributeFilter:['aria-current','aria-pressed','aria-selected']});dispatchEvent(new Event('rei:optics-refresh'));}
 document.addEventListener('click',ev=>{const rotate=ev.target.closest('[data-lab-rotate],[data-lab-reset]');if(rotate){const host=rotate.closest('.lab-heading').querySelector('.lab-heading-object');host.dataset.opticalAngle=rotate.hasAttribute('data-lab-reset')?'0':String((Number(host.dataset.opticalAngle)||0)+Math.PI/4);dispatchEvent(new Event('rei:optics-refresh'))}});
 document.addEventListener('toggle',ev=>{if(!moving()||!ev.target.matches('details')||!ev.target.open)return;const summary=ev.target.querySelector('summary');const a=summary?.animate([{opacity:.6},{opacity:1}],{duration:140});if(a){animations.add(a);a.finished.catch(()=>{}).finally(()=>animations.delete(a))}},true);
 addEventListener('rrh:route',mount);addEventListener('rei:research-render',mount);addEventListener('resize',queue);addEventListener('rrh:motion',()=>{if(!moving()){animations.forEach(a=>a.finish());animations.clear()}dispatchEvent(new Event('rei:optics-refresh'))});mount();
})();
